{
  "document_type": "lease",
  "lessor": "Shantou Yunjia Fashion Clothing Co., Ltd.",
  "lessee": "Shantou Big Tree Toys Co., Ltd",
  "premises_address": "South Part 1, Nanshe Area, Pengnan Industrial Park on North Yingbinbei Road in Waisha Town of Longhu District in Shantou City",
  "area": {
    "value": 1500,
    "unit": "sqm"
  },
  "start_date": "2011-01-01",
  "end_date": "2021-12-31",
  "rent": {
    "amount": 72000,
    "currency": "CNY",
    "period": "year"
  },
  "indexation": "none",
  "red_flags": [
    {
      "type": "sublease_permitted",
      "quote": "Party B has the right of first refusal to lease the property."
    },
    {
      "type": "sublease_permitted",
      "quote": "When the contract expires and Party B fails to find another location to move to, Party B shall negotiate with Party A to extend the lease term."
    },
    {
      "type": "sublease_permitted",
      "quote": "If Party B wants to exchange the use of the property with a third party, Party B shall obtain the consent of Party A, and Party A shall support Party B’s reasonable requests."
    },
    {
      "type": "sublease_permitted",
      "quote": "If Party B subleases the rented space to any other party without the consent of Party A, Party A has the right to request Party B to stop the sublease and terminate this contract."
    },
    {
      "type": "tenant_break_option",
      "quote": "After expiration of this lease contract, if Party B continues to use the property without the consent of Party A, besides regular rent Party B shall pay to Party A the penalty equivalent to 0.05% of the rent for each day after expiration date, and Party A keeps the right to terminate the lease contract."
    },
    {
      "type": "tenant_break_option",
      "quote": "Party B has the right to refuse to pay Party A any other expense except rent."
    }
  ]
}
